-- A call of a SQL function PostgreSQL inlines inside a subquery reads the
-- enclosing query's columns: the plan prints and joins the body in its place.
CREATE FUNCTION f892(integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$SELECT $1 + 1$$;
CREATE TABLE t892 (a integer, b integer);
CREATE TABLE u892 (x integer);
INSERT INTO t892 SELECT g, g % 5 FROM generate_series(1, 100) g;
INSERT INTO u892 SELECT g FROM generate_series(1, 50) g;
ANALYZE t892; ANALYZE u892;
EXPLAIN (COSTS OFF) SELECT (SELECT f892(t892.a) FROM u892 LIMIT 1) FROM t892;
EXPLAIN (COSTS OFF) SELECT (SELECT f892(t892.a)) FROM t892;
EXPLAIN (COSTS OFF) SELECT a FROM t892 WHERE EXISTS (SELECT 1 FROM u892 WHERE u892.x = f892(t892.a));
EXPLAIN (COSTS OFF) SELECT a FROM t892 WHERE a IN (SELECT f892(x) FROM u892);
EXPLAIN (COSTS OFF) SELECT a FROM t892 WHERE NOT EXISTS (SELECT 1 FROM u892 WHERE u892.x = f892(t892.b));
EXPLAIN (COSTS OFF) SELECT * FROM t892 WHERE b = (SELECT max(f892(x)) FROM u892 WHERE x < t892.a);
SELECT count(*) FROM t892 WHERE EXISTS (SELECT 1 FROM u892 WHERE u892.x = f892(t892.a));
SELECT sum((SELECT f892(t892.a))) FROM t892;
